package com.metabuild.modules.admin.audit.application;
import java.nio.charset.StandardCharsets;import java.util.*;
public final class AuditCsv {private AuditCsv(){}public static byte[] operation(List<OperationLogView> rows){var values=new ArrayList<String>();values.add("Operation time,Operator,Module,Type,Target,IP");rows.forEach(x->values.add(row(x.occurredAt(),x.operator(),x.module(),x.type(),x.target(),x.ip())));return bytes(values);}public static byte[] login(List<LoginLogView> rows){var values=new ArrayList<String>();values.add("Login time,User,Result,IP,Location,Device");rows.forEach(x->values.add(row(x.occurredAt(),x.user(),x.result(),x.ip(),x.location(),x.device())));return bytes(values);}private static String row(String... values){return Arrays.stream(values).map(AuditCsv::cell).reduce((a,b)->a+","+b).orElse("");}private static String cell(String value){String safe=value==null?"":value;if(!safe.isEmpty()&&"=+-@\t\r".indexOf(safe.charAt(0))>=0)safe="'"+safe;return "\""+safe.replace("\"","\"\"")+"\"";}private static byte[] bytes(List<String> rows){return ("\ufeff"+String.join("\r\n",rows)+"\r\n").getBytes(StandardCharsets.UTF_8);}}
